      children: "constructor(\nmcqConfig: QuestionConfig,\nmsqConfig: QuestionConfig,\nnatConfig: QuestionConfig\n) {\nthis.mcqConfig = mcqConfig;\nthis.msqConfig = msqConfig;\nthis.natConfig = natConfig;\n}"
